/*
 * 	비트연산자
 * 	  &	 | 	^
 * 			--
 * 			=> 다른 비트 찾기  
 * 		--
 * 	    => +
 * 	 --
 * 	 => *
 */
public class 이항연산자_비트연산자_비트이동연산자 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println(Integer.toBinaryString(100)); // 2진법 // 0b
		System.out.println(Integer.toOctalString(100)); // 8진법 // 0
		System.out.println(Integer.toHexString(100)); // 16진법 // 0x 
	}

}
